export default {
  async main(env, ctx) {
    const p = ctx?.params || {};

    const input = p.targets;
    const maxTargets = Number(p.maxTargets ?? 50) || 50;

    const meta = {
      received: {
        isArray: Array.isArray(input),
        length: Array.isArray(input) ? input.length : 0,
        maxTargets,
      },
      stats: {
        parsed: 0,
        normalized: 0,
        deduped: 0,
        droppedInvalid: 0,
        truncated: false,
      },
      warnings: [],
      errors: [],
      preparedAt: new Date().toISOString(),
    };

    if (!Array.isArray(input)) {
      meta.errors.push('`targets` must be an array of URL strings (e.g. ["https://a.com","https://b.com"])');
      return { outputs: { targets: [], meta } };
    }

    meta.stats.parsed = input.length;

    const seen = new Set();
    const targets = [];

    const normalizeOne = (raw) => {
      let s = String(raw || "").trim();
      if (!s) return null;

      // Allow shorthand: example.com/path -> https://example.com/path
      if (!/^https?:\/\//i.test(s)) {
        if (/^[a-z0-9.-]+\.[a-z]{2,}(\/.*)?$/i.test(s)) s = `https://${s}`;
      }

      try {
        const u = new URL(s);
        if (!/^https?:$/.test(u.protocol)) return null;
        // Remove hash for stable dedupe.
        u.hash = "";
        return u.toString();
      } catch {
        return null;
      }
    };

    for (const raw of input) {
      if (typeof raw !== "string") {
        meta.stats.droppedInvalid += 1;
        continue;
      }

      const normalized = normalizeOne(raw);
      if (!normalized) {
        meta.stats.droppedInvalid += 1;
        continue;
      }

      const key = normalized.toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);

      targets.push({
        url: normalized,
        original: raw,
        host: (() => {
          try {
            return new URL(normalized).host;
          } catch {
            return "";
          }
        })(),
      });

      if (targets.length >= maxTargets) {
        meta.stats.truncated = input.length > maxTargets;
        break;
      }
    }

    meta.stats.normalized = targets.length + meta.stats.droppedInvalid;
    meta.stats.deduped = targets.length;

    if (targets.length === 0) {
      meta.errors.push("No valid URLs found in `targets`.");
    }

    if (meta.stats.truncated) meta.warnings.push(`Too many targets, truncated to ${maxTargets}`);
    if (meta.stats.droppedInvalid > 0) meta.warnings.push(`Dropped ${meta.stats.droppedInvalid} invalid/non-string URLs`);

    return {
      outputs: {
        targets,
        meta,
      },
    };
  },
};

function nowMs() {
  return Date.now();
}

async function withConcurrency(items, concurrency, worker) {
  const arr = Array.isArray(items) ? items : [];
  const c = Math.max(1, Math.min(50, Number(concurrency) || 5));
  const results = new Array(arr.length);
  let idx = 0;

  async function runOne() {
    while (true) {
      const i = idx++;
      if (i >= arr.length) return;
      results[i] = await worker(arr[i], i);
    }
  }

  const pool = new Array(Math.min(c, arr.length)).fill(0).map(() => runOne());
  await Promise.all(pool);
  return results;
}

async function fetchWithTimeout(url, init, timeoutMs) {
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), Math.max(1, Number(timeoutMs) || 10000));
  try {
    const res = await fetch(url, { ...init, signal: controller.signal });
    return res;
  } finally {
    clearTimeout(t);
  }
}

export default {
  async main(env, ctx) {
    const p = ctx?.params || {};
    const upstream = ctx?.upstream || {};

    const prepared = upstream.prepare_targets?.data;
    const targets = Array.isArray(prepared?.outputs?.targets) ? prepared.outputs.targets : [];

    const timeoutMs = Number(p.timeoutMs ?? 10000) || 10000;
    const concurrency = Number(p.concurrency ?? 5) || 5;
    const followRedirects = Boolean(p.followRedirects ?? true);
    const userAgent = String(p.userAgent ?? "Mozilla/5.0 (compatible; Maia-Link-Checker/1.0)");

    const meta = {
      timeoutMs,
      concurrency,
      followRedirects,
      userAgent,
      checkedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
    };

    if (!targets.length) {
      meta.errors.push("Upstream has no valid targets");
      return { outputs: { results: [], meta } };
    }

    const redirect = followRedirects ? "follow" : "manual";

    const results = await withConcurrency(targets, concurrency, async (t) => {
      const url = String(t?.url || "");
      const started = nowMs();

      try {
        const res = await fetchWithTimeout(
          url,
          {
            method: "HEAD",
            redirect,
            headers: {
              "User-Agent": userAgent,
              Accept: "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            },
          },
          timeoutMs
        );

        const latency_ms = nowMs() - started;
        return {
          url,
          method: "HEAD",
          ok: res.status >= 200 && res.status < 400,
          status: res.status,
          final_url: String(res.url || url),
          redirected: Boolean(res.redirected),
          latency_ms,
          error: null,
        };
      } catch (e) {
        const latency_ms = nowMs() - started;
        const msg = e instanceof Error ? e.message : String(e);
        const name = e && typeof e === "object" && "name" in e ? String(e.name) : "";
        const isTimeout = name === "AbortError";
        return {
          url,
          method: "HEAD",
          ok: false,
          status: 0,
          final_url: url,
          redirected: false,
          latency_ms,
          error: isTimeout ? `timeout: ${msg}` : msg,
        };
      }
    });

    return {
      outputs: {
        results,
        meta,
      },
    };
  },
};

function nowMs() {
  return Date.now();
}

