export default {
  async main(env, ctx) {
    const p = ctx?.params || {};
    const upstream = ctx?.upstream || {};

    const head = upstream.head_check?.data;
    const headResults = Array.isArray(head?.outputs?.results) ? head.outputs.results : [];

    const timeoutMs = Number(p.timeoutMs ?? 10000) || 10000;
    const concurrency = Number(p.concurrency ?? 5) || 5;
    const followRedirects = Boolean(p.followRedirects ?? true);
    const userAgent = String(p.userAgent ?? "Mozilla/5.0 (compatible; Maia-Link-Checker/1.0)");

    const meta = {
      timeoutMs,
      concurrency,
      followRedirects,
      userAgent,
      fallbackFor: {
        statuses: [0, 403, 405],
        reason: "When HEAD times out/fails/403/405, use GET for fallback probing (try not to download body)",
      },
      checkedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
    };

    if (!headResults.length) {
      meta.warnings.push("HEAD results are empty: no targets to fallback");
      return { outputs: { results_patch: [], meta } };
    }

    const needsFallback = headResults.filter((r) => {
      const status = Number(r?.status || 0) || 0;
      return status === 0 || status === 403 || status === 405;
    });

    if (!needsFallback.length) {
      return { outputs: { results_patch: [], meta } };
    }

    const redirect = followRedirects ? "follow" : "manual";

    const results_patch = await withConcurrency(needsFallback, concurrency, async (r) => {
      const url = String(r?.url || "");
      const started = nowMs();

      try {
        const res = await fetchWithTimeout(
          url,
          {
            method: "GET",
            redirect,
            headers: {
              "User-Agent": userAgent,
              Accept: "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
              // Try to avoid downloading full body: only fetch first byte (some servers don't support Range, will return 200/full response headers)
              Range: "bytes=0-0",
              "Accept-Encoding": "identity",
            },
          },
          timeoutMs
        );

        // Don't read body (if exists), release resources as soon as possible
        try {
          res.body?.cancel();
        } catch {}

        const latency_ms = nowMs() - started;
        return {
          url,
          method: "GET",
          ok: res.status >= 200 && res.status < 400,
          status: res.status,
          final_url: String(res.url || url),
          redirected: Boolean(res.redirected),
          latency_ms,
          error: null,
        };
      } catch (e) {
        const latency_ms = nowMs() - started;
        const msg = e instanceof Error ? e.message : String(e);
        const name = e && typeof e === "object" && "name" in e ? String(e.name) : "";
        const isTimeout = name === "AbortError";
        return {
          url,
          method: "GET",
          ok: false,
          status: 0,
          final_url: url,
          redirected: false,
          latency_ms,
          error: isTimeout ? `timeout: ${msg}` : msg,
        };
      }
    });

    return {
      outputs: {
        results_patch,
        meta,
      },
    };
  },
};

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};

    const prepared = upstream.prepare_targets?.data;
    const targets = Array.isArray(prepared?.outputs?.targets) ? prepared.outputs.targets : [];

    const head = upstream.head_check?.data;
    const headResults = Array.isArray(head?.outputs?.results) ? head.outputs.results : [];

    const fb = upstream.get_fallback?.data;
    const patch = Array.isArray(fb?.outputs?.results_patch) ? fb.outputs.results_patch : [];

    const meta = {
      mergedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
      stats: {
        targets: targets.length,
        headResults: headResults.length,
        fallbackPatched: patch.length,
      },
    };

    const byUrl = new Map();

    for (const r of headResults) {
      const url = String(r?.url || "");
      if (!url) continue;
      byUrl.set(url, r);
    }

    for (const r of patch) {
      const url = String(r?.url || "");
      if (!url) continue;
      // Fallback results override HEAD
      byUrl.set(url, r);
    }

    const results = [];
    for (const t of targets) {
      const url = String(t?.url || "");
      const r = byUrl.get(url);
      results.push(
        r || {
          url,
          method: null,
          ok: false,
          status: 0,
          final_url: url,
          redirected: false,
          latency_ms: null,
          error: "missing_result",
        }
      );
    }

    const okCount = results.filter((r) => Boolean(r?.ok)).length;
    const failCount = results.length - okCount;

    const summary = {
      total: results.length,
      ok: okCount,
      failed: failCount,
    };

    return {
      outputs: {
        summary,
        results,
        meta,
      },
    };
  },
};

function escMd(s) {
  return String(s ?? "").replace(/\|/g, "\\|").replace(/\r?\n/g, " ");
}

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};

    const merged = upstream.merge_results?.data;
    const summary = merged?.outputs?.summary || { total: 0, ok: 0, failed: 0 };
    const results = Array.isArray(merged?.outputs?.results) ? merged.outputs.results : [];

    const meta = {
      builtAt: new Date().toISOString(),
      errors: [],
      warnings: [],
      wroteFile: false,
      fileName: "link-check-report.md",
      filePath: null,
    };

    const lines = [];
    lines.push(`# Link Availability Report`);
    lines.push("");
    lines.push(`- Generated at: ${new Date().toISOString()}`);
    lines.push(`- Total: ${Number(summary.total || 0)}`);
    lines.push(`- Passed: ${Number(summary.ok || 0)}`);
    lines.push(`- Failed: ${Number(summary.failed || 0)}`);
    lines.push("");

    lines.push("## Results Details");
    lines.push("");
    lines.push("| # | URL | Method | Status | OK | Final URL | Latency(ms) | Error |");
    lines.push("| - | --- | ------ | ------ | -- | --------- | ---------- | ----- |");

    for (let i = 0; i < results.length; i++) {
      const r = results[i] || {};
      const url = escMd(r.url || "");
      const method = escMd(r.method || "-");
      const status = String(r.status ?? "-");
      const ok = r.ok ? "✅" : "❌";
      const finalUrl = escMd(r.final_url || "-");
      const latency = r.latency_ms == null ? "-" : String(r.latency_ms);
      const err = escMd(r.error || "");

      lines.push(`| ${i + 1} | ${url} | ${method} | ${status} | ${ok} | ${finalUrl} | ${latency} | ${err} |`);
    }

    lines.push("");
    lines.push("## Usage Suggestions");
    lines.push("");
    lines.push("- If there are many `timeout` failures: increase `timeoutMs`, or decrease `concurrency`.");
    lines.push("- If HEAD commonly returns 405/403: this is common (many sites disable HEAD), GET fallback will override results.");
    lines.push("- If you're on intranet/CI: ensure DNS/proxy/firewall policies allow access to these domains.");

    const report_md = lines.join("\n");

    try {
      const r = await ctx.artifacts.writeText(meta.fileName, report_md, { kind: "file", summary: "Link check report (Markdown)" });
      meta.wroteFile = true;
      meta.filePath = r?.absPath || null;
    } catch (e) {
      meta.errors.push(`Failed to write/register artifact: ${e instanceof Error ? e.message : String(e)}`);
    }

    return {
      outputs: {
        report_md,
        file_name: meta.fileName,
        file_path: meta.filePath,
        wrote_file: meta.wroteFile,
        meta,
      },
    };
  },
};
